from fastapi import FastAPI, HTTPException
from fastapi.testclient import TestClient
from pydantic import BaseModel

app = FastAPI()
TASKS = {}
NEXT_ID = 1


class TaskIn(BaseModel):
    title: str
    done: bool = False


@app.post("/tasks", status_code=201)
def create_task(task: TaskIn):
    global NEXT_ID
    TASKS[NEXT_ID] = {"id": NEXT_ID, "title": task.title, "done": task.done}
    NEXT_ID += 1
    return TASKS[NEXT_ID - 1]


@app.get("/tasks")
def list_tasks():
    return list(TASKS.values())


@app.get("/tasks/{task_id}")
def get_task(task_id: int):
    if task_id not in TASKS:
        raise HTTPException(status_code=404, detail="Задача не найдена")
    return TASKS[task_id]


client = TestClient(app)
client.post("/tasks", json={"title": "Купить молоко"})
client.post("/tasks", json={"title": "Написать отчёт", "done": True})
print(client.get("/tasks").json())
print(client.get("/tasks/2").json())
print(client.get("/tasks/9").status_code)

